use super::*;

/// The document one mode writes. `None` fields are the CLEARS — see the module doc.
pub fn doc_for(mode: &str, d: &ModeDefaults) -> Result<SessionDoc, String> {
    match mode {
        "local" => Ok(SessionDoc {
            provider: Some("ollama".into()),
            model: Some(d.local_model.clone()),
            base_url: Some(d.local_base_url.clone()),
            num_ctx: Some(d.local_num_ctx),
            ..Default::default()
        }),
        "claude" => Ok(SessionDoc {
            provider: Some("anthropic".into()),
            model: Some(d.anthropic_model.clone()),
            // CLEARED, not carried: a Claude model pointed at a localhost base URL is the
            // half-switched state this verb exists to prevent.
            base_url: None,
            num_ctx: None,
            ..Default::default()
        }),
        other => Err(format!("'{other}' is not a mode. Valid: {}", MODES.join(" · "))),
    }
}
